    else:
        raise ValueError(f"unknown agent type: {atype}")

    write_metric_line(metrics_path, {
        "record_type": "header",
        "runner": "bandit",
        "seed": int(cfg.seed),
        "env": {"probs": cfg.probs, "horizon": int(cfg.horizon)},
