                mse = abs(float(fb.get("reward", 0.0))) * 4.5
            except Exception:
                pass
        pressure = 0.5 * mse + 0.5 * cp

        rm_gamma = cal.get("gamma_rm")
        if callable(rm_gamma):
            try:
                self.gamma, cal["gamma_rm"] = rm_gamma(self.gamma, pressure)
            except Exception:
                pass

        rm_lambda = cal.get("lambda_rm")
        if callable(rm_lambda):
            try:
                self.lam_mdl, cal["lambda_rm"] = rm_lambda(self.lam_mdl, pressure)
            except Exception:
                pass

        k_new = 1
        if (res == {} and probes == {}):
            k_new = 0  # fallback path: don't penalize missing residuals
        mdl_gain   = self._mdl_gain(mse, k_new=k_new)
        want_birth = (pressure > self.gamma) and (mdl_gain > 0.0)

        born = False
        cap_hits = 0
        if want_birth:
            if budget is None:
                born = True
            else:
                try:
                    if budget.allow_move("birth") and budget.commit("birth"):
                        born = True
                        self.last_birth_t = t
                    else:
                        cap_hits = 1
                except Exception:
                    pass

        return {"born_variable": born, "pressure": pressure, "mdl_gain": mdl_gain, "cap_hits": int(cap_hits)}

    def update(self, observation: Dict[str, Any], primitives: Dict[str, Any], header: Any, feedback: Dict[str, Any] | None) -> Dict[str, Any]:
        # Only update when we have outcome-bearing signals (prevents decision-pass overwrite).
        if not (observation.get("residuals") or observation.get("probes") or observation.get("feedback") or feedback):
            return {}
        out = self._run_core(observation, primitives, header, feedback)
        try:
            from agents.co.core.primitives.P10_change_ops_core import ChangeOpsCore
            from agents.co.core.primitives.P12_closure_quotient import ClosureQuotient
            from agents.co.core.primitives.identity import bend_distance
        except Exception:
            ChangeOpsCore = None
            ClosureQuotient = None
            bend_distance = None

        # ensure P10 exists if birth was accepted
        p10 = primitives.get("P10")
        if p10 is None and out.get("born_variable") and ChangeOpsCore is not None:
            p10 = ChangeOpsCore(k=4, epsilon=1.0)
            primitives["P10"] = p10

        # wire birth into a concrete state mutation (P10/P12), minimal + safe
        if out.get("born_variable") and p10 is not None:
            # create a prototype from recent history (or a tiny unique token)
            proto = None
            hist = list(observation.get("history", ()))
            if hasattr(p10, "k") and hist:
                k = max(1, int(getattr(p10, "k", 1)))
                if len(hist) >= k:
                    proto = tuple(hist[-k:])
                else:
                    proto = tuple(hist)
            if proto is None:
                proto = (f"born_{observation.get('family','')}", int(observation.get("t", 0)))
            try:
                if hasattr(p10, "prototypes"):
                    if proto not in p10.prototypes:
                        p10.prototypes.append(proto)
            except Exception:
                pass

        # compute current counts (even if no birth) for telemetry
        prototype_count = len(getattr(p10, "prototypes", [])) if p10 is not None else 0
        class_count = 0
        if bend_distance is not None and p10 is not None and hasattr(p10, "prototypes"):
            prototypes = list(getattr(p10, "prototypes", []))
            if prototypes:
                p12 = primitives.get("P12")
                if p12 is None and ClosureQuotient is not None:
                    p12 = ClosureQuotient(epsilon=getattr(p10, "epsilon", 0.0))
                    primitives["P12"] = p12
                if p12 is not None and hasattr(p12, "closure"):
                    try:
                        classes = p12.closure(prototypes, bend_distance)
                        class_count = len(classes)
                    except Exception:
                        class_count = 0

        out["birth_events"] = 1 if out.get("born_variable") else 0
        out["prototype_count"] = int(prototype_count)
        out["class_count"] = int(class_count)
        # merge/split are not fully modeled; log minimal counters
        out["merge_events"] = max(0, int(prototype_count) - int(class_count)) if class_count else 0
        out["split_events"] = 0

        bus = primitives.get("co_bus")
        publish_signal(bus, "EB_GHVC.pressure",  out.get("pressure", 0.0))
        publish_signal(bus, "EB_GHVC.mdl_gain",  out.get("mdl_gain", 0.0))
        publish_signal(bus, "EB_GHVC.birth_suggest", 1.0 if out.get("born_variable") else 0.0)
        publish_signal(bus, "birth_events", float(out.get("birth_events", 0)))
        publish_signal(bus, "merge_events", float(out.get("merge_events", 0)))
        publish_signal(bus, "split_events", float(out.get("split_events", 0)))
        publish_signal(bus, "prototype_count", float(out.get("prototype_count", 0)))
        publish_signal(bus, "class_count", float(out.get("class_count", 0)))
        publish_signal(bus, "cap_hits", float(out.get("cap_hits", 0)))
        return out

    def step(self, observation: Dict[str, Any], primitives: Dict[str, Any], header: Any, feedback: Dict[str, Any] | None) -> Dict[str, Any]:
        return self.update(observation, primitives, header, feedback)

