                                state["_debug_header_updates"] = cur + 1
                            except Exception:
                                pass
            except Exception:
                pass
        except Exception:
            pass

        for e in elements:
            if e.__class__.__name__.lower().endswith("actionhead"):
                continue  # skip the head on update pass

            if hasattr(e, "update"):
                try:
                    u = e.update(obs, primitives, header, feedback)
                    if isinstance(u, dict) and u:
                        out.update(u)
                except Exception:
                    pass

